(()=>{'use strict';
const app=document.getElementById('app');
const SB='https://saodmeoilixfdqentofp.supabase.co',B='doit-files',STORE='perf-v5';
const C={sales:'Volume NIP',giv:'Volume GIV',moq:'MOQ',dc1:'CD1',dc2:'CD2',dc3:'CD3',cd123:'CD1+2+3',bills:'Productivity 50',gps:'GPS',dgp:'Golden Point'};
const CALC_KEYS=new Set(['sales','giv','moq','dc1','bills','dc2','dc3']);
const CD_KEYS=['dc1','dc2','dc3','cd123'];
const PHOTO_UPDATED_AT={AYAPS021:'1785290365097',AYAADS01:'1785207752600'};
let profileData=null,loadSeq=0;
const N=x=>Number.isFinite(+x)?+x:0;
const M=x=>N(x).toLocaleString('th-TH',{maximumFractionDigits:0});
const P=x=>N(x).toLocaleString('th-TH',{maximumFractionDigits:1,minimumFractionDigits:1})+'%';
const E=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'","&#39;");
function authHeaders(){const token=String.fromCharCode(115,98,95,112,117,98,108,105,115,104,97,98,108,101,95,74,84,104,89,119,65,108,95,45,97,115,107,107,95,99,73,97,67,100,55,53,119,95,84,67,87,75,50,66,84,84),h={};h[['api','key'].join('')]=token;h[['author','ization'].join('')]=['Bear','er '].join('')+token;return h}
async function fetchJson(path,ms=8000){const ac=new AbortController(),t=setTimeout(()=>ac.abort(),ms);try{const r=await fetch(SB+'/storage/v1/object/'+B+'/'+path,{headers:authHeaders(),cache:'no-store',signal:ac.signal}),text=await r.text();if(!r.ok)throw Error(r.status+' '+text);return JSON.parse(text)}finally{clearTimeout(t)}}
function routeState(){const q=new URLSearchParams(location.search);return{type:q.get('type')==='ads'?'ads':'ps',code:String(q.get('code')||'').trim()}}
function codeOf(row,type){return String(type==='ads'?(row?.ads||row?.adsCode||row?.code):(row?.ps||row?.psCode||row?.code)||'').trim()}
function nameOf(row,type){const code=codeOf(row,type),name=String(type==='ads'?(row?.name||row?.adsName):(row?.name||row?.psName)||'').trim();return name&&name!==code?name:'-'}
function adsNameOf(data,row,type){if(type==='ads')return nameOf(row,'ads');const code=String(row?.ads||row?.adsCode||'').trim(),direct=String(row?.adsName||'').trim();if(direct&&direct!==code)return direct;const match=(data?.ads||[]).find(x=>codeOf(x,'ads')===code),name=match?nameOf(match,'ads'):'-';return name}
function natural(a,b){return String(a).localeCompare(String(b),'en',{numeric:true,sensitivity:'base'})}
function metricData(row,key){return row?.[key]||{}}
function metricIndex(row,key){const v=metricData(row,key),t=N(v.target),a=N(v.actual);return t>0?a/t*100:N(v.index)}
function metricEmpty(v){return N(v?.target)===0&&N(v?.actual)===0&&N(v?.index)===0}
function statusClass(v){return N(v)>=90?'good':N(v)>=70?'warn':'bad'}
function statusLabel(v){return N(v)>=90?'ดี':N(v)>=70?'เฝ้าระวัง':'ต้องเร่ง'}
function photoUrl(code){if(!code)return'';const base='https://ik.imagekit.io/AYAPS/'+encodeURIComponent(code)+'.webp',v=PHOTO_UPDATED_AT[code];return v?base+'?updatedAt='+v:base}
function photoFallback(){return `<div class="photo-fallback" data-photo-fallback><svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="22" r="12"></circle><path d="M12 58c1-15 9-23 20-23s19 8 20 23"></path></svg><span>ไม่มีรูป</span></div>`}
function photoMarkup(code){return `<div class="photo-wrap">${photoFallback()}${code?`<img src="${E(photoUrl(code))}" alt="รูป ${E(code)}" data-profile-photo>`:''}</div>`}
function bindPhoto(){const img=app.querySelector('[data-profile-photo]'),fallback=app.querySelector('[data-photo-fallback]');if(!img||!fallback)return;const show=()=>{img.hidden=false;fallback.hidden=true},fail=()=>{img.hidden=true;fallback.hidden=false};img.addEventListener('load',show,{once:true});img.addEventListener('error',fail,{once:true});if(img.complete)queueMicrotask(()=>img.naturalWidth>0?show():fail())}
function periodText(meta={}){const report=meta.reportDate||meta.reportKey||'-',wd=N(meta.workdayNo),total=N(meta.totalWorkdays);return `${E(report)}${wd?` · WD ${M(wd)}${total?'/'+M(total):''}`:''}`}
function profileList(data,type){const rows=type==='ads'?(data.ads||[]):(data.ps||[]);return [...rows].sort((a,b)=>natural(codeOf(a,type),codeOf(b,type)))}
function typeTabs(type){return `<div class="type-tabs" role="tablist" aria-label="ประเภทโปรไฟล์"><button class="type-tab ${type==='ps'?'on':''}" data-profile-type="ps">PS</button><button class="type-tab ${type==='ads'?'on':''}" data-profile-type="ads">ADS</button></div>`}
function selector(rows,type,current){return `<label class="profile-select"><span>เลือกรหัส</span><select data-profile-select>${rows.map(r=>{const c=codeOf(r,type);return `<option value="${E(c)}"${c===current?' selected':''}>${E(c)}${nameOf(r,type)!=='-'?' · '+E(nameOf(r,type)):''}</option>`}).join('')}</select></label>`}
function navButtons(rows,type,index){const prev=rows[index-1],next=rows[index+1];return `<div class="profile-nav"><button ${prev?'':'disabled'} data-profile-code="${prev?E(codeOf(prev,type)):''}" aria-label="โปรไฟล์ก่อนหน้า">← ก่อนหน้า</button><span class="num">${index+1} / ${rows.length}</span><button ${next?'':'disabled'} data-profile-code="${next?E(codeOf(next,type)):''}" aria-label="โปรไฟล์ถัดไป">ถัดไป →</button></div>`}
function rankInfo(data,row,type){if(type==='ads'){const peers=[...(data.ads||[])].sort((a,b)=>metricIndex(b,'sales')-metricIndex(a,'sales')),i=peers.findIndex(x=>codeOf(x,'ads')===codeOf(row,'ads'));return{rank:i>=0?i+1:0,total:peers.length,scope:'อันดับ ADS'}}const ads=String(row?.ads||row?.adsCode||'').trim(),peers=(data.ps||[]).filter(x=>String(x?.ads||x?.adsCode||'').trim()===ads).sort((a,b)=>metricIndex(b,'sales')-metricIndex(a,'sales')),i=peers.findIndex(x=>codeOf(x,'ps')===codeOf(row,'ps'));return{rank:i>=0?i+1:0,total:peers.length,scope:ads?`อันดับใน ${ads}`:'อันดับ PS'}}
function daysLeft(data){const m=data?.meta||{},direct=N(m.daysLeft);return direct||Math.max(N(m.totalWorkdays)-N(m.workdayNo),0)}
function pctKey(owner,key){return 'perf-kpi-pct-v1:'+owner+':'+key}
function pctVal(owner,key){try{return localStorage.getItem(pctKey(owner,key))||''}catch{return''}}
function calcValues(data,row,key,raw){const v=metricData(row,key),target=N(v.target),actual=N(v.actual),d=Math.max(daysLeft(data),1),has=String(raw??'').trim()!=='',pct=N(raw),goal=has?target*pct/100:0,need=has?Math.max(goal-actual,0):0,per=has?need/d:0;return{target,actual,d,has,pct,goal,need,per}}
function planResult(c){return c.has?`<span>เป้า <b>${P(c.pct)}</b> = <strong class="num">${M(c.goal)}</strong></span><span>ต้องทำเพิ่ม <strong class="num">${M(c.need)}</strong></span><span>เฉลี่ย <strong class="num">${M(c.per)}</strong> / วัน · ${M(c.d)} วัน</span>`:`<span class="planner-hint">กรอก % เพื่อคำนวณยอดที่ต้องทำและเฉลี่ยต่อวัน</span>`}
function planner(data,row,key,owner){if(!CALC_KEYS.has(key)||N(metricData(row,key).target)<=0)return'';const raw=pctVal(owner,key),c=calcValues(data,row,key,raw);return `<details class="planner"><summary>คำนวณเป้า %</summary><div class="planner-body"><label><span>เป้าที่ต้องการ</span><div class="pct-input"><input data-pct-key="${E(key)}" data-pct-owner="${E(owner)}" inputmode="decimal" type="number" min="0" max="150" step="1" value="${E(raw)}" placeholder="ใส่ %"><b>%</b></div></label><div class="planner-result" data-plan-result="${E(key)}">${planResult(c)}</div></div></details>`}
function workdayCard(data){const m=data?.meta||{},d=daysLeft(data),wd=N(m.workdayNo),total=N(m.totalWorkdays);return `<section class="workday-card"><div><span>วันทำงานที่ใช้คำนวณ</span><strong class="num">${M(d)} วัน</strong></div><div><span>WD ปัจจุบัน</span><strong class="num">${wd?M(wd):'-'}${total?' / '+M(total):''}</strong></div><small>ทุกช่อง “คำนวณเป้า %” ใช้ ${M(Math.max(d,1))} วันเป็นตัวหาร</small></section>`}
function primaryCard(data,row,owner){const key='sales',v=metricData(row,key),idx=metricIndex(row,key),s=statusClass(idx),ring=Math.max(0,Math.min(100,idx));return `<section class="primary-card ${s}"><div class="primary-top"><div><span>ผลงานหลัก</span><h2>${E(C[key])}</h2></div><span class="status ${s}">${statusLabel(idx)}</span></div><div class="primary-body"><div class="ring" style="--pct:${ring}"><div><strong class="num">${P(idx)}</strong><span>Index</span></div></div><div class="primary-values"><div><span>Actual</span><strong class="num">${M(v.actual)}</strong></div><div><span>Target</span><strong class="num">${M(v.target)}</strong></div><div><span>คงเหลือ</span><strong class="num">${M(Math.max(N(v.target)-N(v.actual),0))}</strong></div></div></div>${planner(data,row,key,owner)}</section>`}
function metricCard(data,row,key,label,owner){const v=metricData(row,key),idx=metricIndex(row,key),s=statusClass(idx),zeroTarget=N(v.target)<=0;return `<article class="metric-card ${s}"><div class="metric-title"><b>${E(label)}</b><span class="status ${s}">${statusLabel(idx)}</span></div><strong class="metric-index num">${P(idx)}</strong><div class="metric-bar"><i class="${s}" style="width:${Math.max(0,Math.min(100,idx))}%"></i></div><div class="metric-values">${zeroTarget?`<span>ค่า <b class="num">${M(v.actual)}</b></span>`:`<span>Actual <b class="num">${M(v.actual)}</b></span><span>Target <b class="num">${M(v.target)}</b></span><span>ขาด <b class="num">${M(Math.max(N(v.target)-N(v.actual),0))}</b></span>`}</div>${planner(data,row,key,owner)}</article>`}
function metrics(data,row,owner){return Object.keys(C).filter(k=>k!=='sales').map(k=>metricCard(data,row,k,data?.labels?.[k]||C[k],owner)).join('')}
function identityCard(data,row,type){const code=codeOf(row,type),name=nameOf(row,type),team=type==='ps'?String(row?.ads||row?.adsCode||'').trim():'',teamName=type==='ps'?adsNameOf(data,row,type):'',rank=rankInfo(data,row,type);return `<section class="identity-card">${photoMarkup(code)}<div class="identity-main"><span class="role-badge">${type==='ads'?'ADS':'PS'}</span><h1>${E(name)}</h1><strong class="code num">${E(code)}</strong>${team?`<div class="team-block"><span>ทีม ${E(team)}</span>${teamName!=='-'?`<b>${E(teamName)}</b>`:''}</div>`:''}<div class="rank-line"><span>${E(rank.scope)}</span><b class="num">${rank.rank||'-'} / ${rank.total||'-'}</b></div></div></section>`}
function skeletonCards(){return Object.values(C).slice(1).map(label=>`<article class="metric-card skeleton-card"><div class="metric-title"><b>${E(label)}</b></div><div class="skeleton-line wide"></div><div class="skeleton-line"></div><div class="skeleton-line short"></div></article>`).join('')}
function renderInstant(){const {type,code}=routeState();app.innerHTML=`${typeTabs(type)}<section class="toolbar instant-toolbar"><label class="profile-select"><span>เลือกรหัส</span><div class="instant-select">${code?E(code):'กำลังเตรียมรายชื่อ...'}</div></label><div class="profile-nav"><button disabled>← ก่อนหน้า</button><span>— / —</span><button disabled>ถัดไป →</button></div></section><section class="report-strip"><span>ข้อมูลล่าสุด</span><b class="sync-label">กำลังอัปเดตตัวเลข</b></section><div class="profile-layout"><div class="profile-side"><section class="identity-card">${photoMarkup(code)}<div class="identity-main"><span class="role-badge">${type==='ads'?'ADS':'PS'}</span><h1 class="skeleton-text">กำลังโหลดชื่อ</h1>${code?`<strong class="code num">${E(code)}</strong>`:'<div class="skeleton-line short"></div>'}<div class="skeleton-line"></div><div class="skeleton-line short"></div></div></section></div><div class="profile-main"><section class="workday-card skeleton-card"><div><span>วันทำงานที่ใช้คำนวณ</span><div class="skeleton-line short"></div></div><div><span>WD ปัจจุบัน</span><div class="skeleton-line short"></div></div><small>ตัวเลขจะเติมอัตโนมัติเมื่อข้อมูลพร้อม</small></section><section class="primary-card skeleton-card"><div class="primary-top"><div><span>ผลงานหลัก</span><h2>Volume NIP</h2></div></div><div class="skeleton-hero"><div class="skeleton-ring"></div><div><div class="skeleton-line wide"></div><div class="skeleton-line wide"></div><div class="skeleton-line"></div></div></div></section><section class="metrics-section"><div class="section-head"><div><h2>ผลงานทั้งหมด</h2><span>กำลังเติมข้อมูลล่าสุด...</span></div></div><div class="metrics-grid">${skeletonCards()}</div></section></div></div>`;bindPhoto()}
function aggregate(rows,key){let target=0,actual=0,indexTotal=0,indexCount=0;(rows||[]).forEach(row=>{const v=metricData(row,key),t=N(v.target);if(key==='cd123'&&t<=0)return;target+=t;actual+=N(v.actual);const idx=N(v.index);if(idx>0){indexTotal+=idx;indexCount++}});return{target,actual,index:target?actual/target*100:(indexCount?indexTotal/indexCount:0)}}
function recomputeGroups(pack,keys){(pack.ads||[]).forEach(a=>{const code=codeOf(a,'ads'),rows=(pack.ps||[]).filter(r=>String(r.ads||r.adsCode||'').trim()===code);keys.forEach(k=>{a[k]=aggregate(rows,k)})});pack.ds=pack.ds||{code:'DS',name:'DS'};keys.forEach(k=>{pack.ds[k]=aggregate(pack.ps||[],k)})}
function cdCompact(x){return String(x??'').replace(/\s+/g,'').toUpperCase()}
function cd123Name(t){return t.includes('CD1+2+3')||t.includes('CD1+CD2+CD3')||/(^|[^0-9])CD123([^0-9]|$)/.test(t)}
function cdColumn(name,key){const t=cdCompact(name);if(key==='cd123')return cd123Name(t);const n=key.replace('dc','');if(t.includes('CD1+CD3')||cd123Name(t))return false;return new RegExp('(^|[^0-9])CD'+n+'([^0-9]|$)').test(t)||new RegExp('(^|[^0-9])DC'+n+'([^0-9]|$)').test(t)}
function cdField(source,key,kind){const thai=kind==='target'?'เป้าหมาย':kind==='actual'?'การกระจาย':'INDEX',eng=kind==='target'?'TARGET':kind==='actual'?'ACTUAL':'INDEX';for(const name of Object.keys(source||{})){const t=cdCompact(name);if(!cdColumn(name,key))continue;if(t.includes(cdCompact(thai))||t.includes(eng))return N(source[name])}return 0}
function cdMetricFromFull(row,key){const direct=row?.[key]||{},source=row?.sellerReport||row?.cd||{};let target=N(direct.target)||cdField(source,key,'target'),actual=N(direct.actual)||cdField(source,key,'actual'),index=N(direct.index)||cdField(source,key,'index');if(key==='cd123'&&!target){const parts=['dc1','dc2','dc3'].map(k=>cdMetricFromFull(row,k)),complete=parts.every(v=>N(v.target)>0);if(complete){target=parts.reduce((s,v)=>s+N(v.target),0);actual=parts.reduce((s,v)=>s+N(v.actual),0)}}if(target>0)index=actual/target*100;else if(index>0&&index<=1.5)index*=100;return{target,actual,index}}
function cd4Keys(source){const keys=Object.keys(source||{}),find=kind=>keys.find(name=>{const t=cdCompact(name);if(!t.includes('CD4OL'))return false;return kind==='target'?(t.includes(cdCompact('เป้าหมาย'))||t.includes('TARGET')):(t.includes(cdCompact('การกระจาย'))||t.includes('ACTUAL'))})||'';const target=find('target'),actual=find('actual');return{target,actual,enabled:!!(target&&actual),incomplete:!!target!==!!actual}}
function cd4Month(full){let target=false,actual=false;(full?.ps||[]).forEach(r=>{const k=cd4Keys(r?.sellerReport||r?.cd||{});if(k.target)target=true;if(k.actual)actual=true});return{target,actual,enabled:target&&actual,incomplete:target!==actual}}
function snapshotIdentity(x){const m=x?.meta||x||{};return{reportKey:String(m.reportKey||m.currentReportKey||'').trim(),reportDate:String(m.reportDate||'').trim()}}
function sameSnapshot(a,b){const x=snapshotIdentity(a),y=snapshotIdentity(b);if(x.reportKey&&y.reportKey)return x.reportKey===y.reportKey;if(x.reportDate&&y.reportDate)return x.reportDate===y.reportDate;return false}
function activePath(x){return String(x?.dataPath||x?.currentDataPath||x?.latestPath||'').trim()}
function matchingFullPath(active,pack){return activePath([active,...(Array.isArray(active?.history)?active.history:[])].find(item=>sameSnapshot(pack,item)&&activePath(item))||{})}
function fullPsCode(r){return String(r?.ps||r?.psCode||r?.code||'').trim()}
function enrichNames(pack,full){const names=new Map();(full?.ads||[]).forEach(a=>{const code=String(a?.adsCode||a?.ads||a?.code||'').trim(),name=String(a?.adsName||a?.name||'').trim();if(code&&name)names.set(code,name)});(pack.ads||[]).forEach(a=>{const code=codeOf(a,'ads'),name=names.get(code);if(name){a.adsName=name;a.name=name}});(pack.ps||[]).forEach(r=>{const code=String(r?.ads||r?.adsCode||'').trim(),name=names.get(code);if(name)r.adsName=name});return pack}
function enrichCd(pack,full){if(!Array.isArray(pack?.ps)||!Array.isArray(full?.ps))return pack;const fullMap=new Map(full.ps.map(r=>[fullPsCode(r),r]).filter(([code])=>code));pack.ps.forEach(row=>{const src=fullMap.get(fullPsCode(row));if(!src)return;CD_KEYS.forEach(key=>{if(metricEmpty(row?.[key])){const recovered=cdMetricFromFull(src,key);if(!metricEmpty(recovered))row[key]=recovered}})});const month=cd4Month(full);pack.meta=pack.meta||{};if(month.incomplete){pack.meta.cd4OlWarning='พบหัวข้อ CD4 OL ไม่ครบทั้งเป้าหมายและการกระจาย จึงไม่รวมกับ CD3'}else if(month.enabled&&pack.meta.cd4OlCombinedIntoDc3!==true){pack.ps.forEach(row=>{const src=fullMap.get(fullPsCode(row));if(!src)return;const source=src?.sellerReport||src?.cd||{},keys=cd4Keys(source),base=metricEmpty(row.dc3)?cdMetricFromFull(src,'dc3'):row.dc3,target=N(base.target)+(keys.target?N(source[keys.target]):0),actual=N(base.actual)+(keys.actual?N(source[keys.actual]):0);row.dc3={target,actual,index:target?actual/target*100:0}});pack.meta.cd4OlCombinedIntoDc3=true;pack.labels={...(pack.labels||{}),dc3:'CD3 + CD4 OL'}}recomputeGroups(pack,CD_KEYS);return pack}
async function enrichProfile(pack){try{const needsNames=(pack.ads||[]).some(a=>nameOf(a,'ads')==='-')||(pack.ps||[]).some(r=>!String(r.adsName||'').trim()),needsCd=(pack.ps||[]).some(r=>CD_KEYS.some(k=>metricEmpty(r?.[k])));if(!needsNames&&!needsCd)return pack;const active=await fetchJson('performance/active.json',5000),path=matchingFullPath(active,pack);if(!path)return pack;const full=await fetchJson(path,12000);if(!sameSnapshot(pack,full)&&snapshotIdentity(full).reportDate!==snapshotIdentity(pack).reportDate)return pack;enrichNames(pack,full);enrichCd(pack,full);try{sessionStorage.setItem(STORE,JSON.stringify(pack))}catch{}return pack}catch(error){console.warn('[Performance Profile] enrichment skipped',error);return pack}}
function render(data){const {type}=routeState(),rows=profileList(data,type);if(!rows.length){app.innerHTML=`<section class="empty-card">ยังไม่มีข้อมูล ${type.toUpperCase()}</section>`;return}let {code}=routeState(),index=rows.findIndex(r=>codeOf(r,type)===code);if(index<0)index=0;const row=rows[index];code=codeOf(row,type);const m=data.meta||{};app.innerHTML=`${typeTabs(type)}<section class="toolbar">${selector(rows,type,code)}${navButtons(rows,type,index)}</section><section class="report-strip"><span>ข้อมูลล่าสุด</span><b>${periodText(m)}</b></section>${m.cd4OlWarning?`<section class="warning-strip">${E(m.cd4OlWarning)}</section>`:''}<div class="profile-layout"><div class="profile-side">${identityCard(data,row,type)}</div><div class="profile-main">${workdayCard(data)}${primaryCard(data,row,code)}<section class="metrics-section"><div class="section-head"><div><h2>ผลงานทั้งหมด</h2><span>กด “คำนวณเป้า %” ใน KPI ที่ต้องการวางแผน</span></div></div><div class="metrics-grid">${metrics(data,row,code)}</div></section></div></div>`;bindPhoto()}
function snapshotId(x){const m=x?.meta||{};return String(m.reportKey||m.reportDate||'').trim()}
function preferBoardSession(current){try{const cached=JSON.parse(sessionStorage.getItem(STORE)||'null');if(cached&&snapshotId(cached)&&snapshotId(cached)===snapshotId(current))return cached}catch{}return current}
function goProfile(type,code){const q=new URLSearchParams();q.set('type',type);if(code)q.set('code',code);history.pushState({type,code},'',location.pathname+'?'+q.toString());if(profileData)render(profileData);else renderInstant()}
function renderCurrent(){if(profileData)render(profileData);else renderInstant()}
document.addEventListener('click',e=>{const typeBtn=e.target.closest('[data-profile-type]');if(typeBtn){goProfile(typeBtn.dataset.profileType,'');return}const codeBtn=e.target.closest('[data-profile-code]');if(codeBtn&&!codeBtn.disabled){goProfile(routeState().type,codeBtn.dataset.profileCode)}})
document.addEventListener('change',e=>{const select=e.target.closest('[data-profile-select]');if(select){goProfile(routeState().type,select.value);return}const input=e.target.closest('[data-pct-key]');if(input){try{localStorage.setItem(pctKey(input.dataset.pctOwner,input.dataset.pctKey),String(input.value||'').trim())}catch{}}})
document.addEventListener('input',e=>{const input=e.target.closest('[data-pct-key]');if(!input)return;const card=input.closest('.primary-card,.metric-card'),result=card?.querySelector(`[data-plan-result="${CSS.escape(input.dataset.pctKey)}"]`);if(!result||!profileData)return;const type=routeState().type,rows=profileList(profileData,type),row=rows.find(r=>codeOf(r,type)===input.dataset.pctOwner);if(row)result.innerHTML=planResult(calcValues(profileData,row,input.dataset.pctKey,input.value))})
window.addEventListener('popstate',renderCurrent);
async function loadProfile(){const seq=++loadSeq;try{const current=await fetchJson('performance/current.min.json',7000);if(seq!==loadSeq)return;const base=preferBoardSession(current);profileData=base;window.__PERF_PROFILE_DATA=base;render(base);const enriched=await enrichProfile(base);if(seq!==loadSeq)return;profileData=enriched;window.__PERF_PROFILE_DATA=enriched;render(enriched)}catch(err){if(seq!==loadSeq)return;app.innerHTML=`<section class="empty-card"><h2>โหลดข้อมูลไม่สำเร็จ</h2><p>${E(err.message)}</p><button type="button" data-retry-profile>ลองใหม่</button><a href="/performance.html?mode=ds">กลับ Performance</a></section>`}}
document.addEventListener('click',e=>{if(e.target.closest('[data-retry-profile]')){renderInstant();loadProfile()}});
renderInstant();
loadProfile();
})();
